// Normalize & Detect Language (deterministic, no AI yet)
// Supports: English + Arabic, Text + Voice, LEAD vs INFO

// 1. Get all incoming items (voice branch + text branch converge here)
const all = $input.all();
// Pick item that has question/text, fallback to first
const item = (all.find(i => i.json.question || i.json.text) || all[0]).json;

// 2. Raw user question
const raw = (item.question || item.text || '').toString();
const text = raw.trim();

// 3. Contact info (kept for WhatsApp reply)
const phone = item.phone || '+971501111222';
const chat_id = item.chat_id || `${phone}@s.whatsapp.net`;
const message_id = item.message_id || `msg_${Date.now()}`;

// 4. Language detection - Arabic if Arabic chars present
const isAr = /[\u0600-\u06FF]/.test(text);
const language = isAr ? 'ar' : 'en';
const lower = text.toLowerCase(); // for English keyword matching, Arabic stays same

// 5. Voice detection - true if any input was voice
// Voice path: Set Question sets is_voice=true, Text path: Normalize WhatsApp sets is_voice=false
const is_voice = all.some(i => i.json.is_voice === true) || item.is_voice === true || false;

// 6. LEAD keywords = user wants to buy/rent/search property
const leadKw = [
  // EN - buying intent
  'buy','rent','looking for','looking','want','need','search','budget','million','aed',
  'bhk','2br','1br','3br','studio','apartment','villa','townhouse','marina','downtown','palm','hills','invest','ready',
  // AR - نية الشراء / البحث
  'ابحث','ابحث عن','ابغى','اريد','بدي','محتاج','شقة','شقق','غرفة','غرفتين','غرف','صالة','فيلا','استوديو','مارينا','داون تاون','وسط المدينة','تلال','نخلة','ميزانية','مليون','درهم','شراء','ايجار','استثمار','مطلوب','جاهز'
];

// 7. INFO keywords = user asks about fees/procedure
const infoKw = [
  // EN - fee / procedure questions
  'fee','fees','dld','transfer','registration','trustee','commission','service charge','ejari','mortgage','cost','charges','what is','how much','how to','procedure','process','explain',
  // AR - استفسار عن الرسوم
  'رسوم','الرسوم','دائرة الاراضي','نقل','تسجيل','امين التسجيل','عمولة','رسوم الخدمة','ايجاري','رهن','تكلفة','مصاريف','كم','ما هي','ما هو','كيف','اشرح','اجراءات'
];

// 8. Check if text contains LEAD or INFO keywords
const hasLead = leadKw.some(k => lower.includes(k));
const hasInfo = infoKw.some(k => lower.includes(k));

// 9. Strong LEAD signal = budget / price mentioned (2M, 2 مليون, budget, ميزانية)
const numberBudget = /\d+(\.\d+)?\s*(m|million|مليون|k|aed|درهم)/i.test(text);
const isFeeQuestion = /what are|what is|how much|fee|رسوم|كم|ما هي/i.test(text);
const budgetPattern = numberBudget && !isFeeQuestion; // price alone = LEAD, price + fee word = INFO

// 10. Decide quick_intent
// - Only INFO keywords -> INFO (ex: "What are DLD fees?" / "ما هي رسوم التسجيل؟")
// - Only LEAD keywords -> LEAD (ex: "Looking for 2BR Marina" / "ابحث عن شقة")
// - Both -> if budget present -> LEAD, else INFO
// - None -> INFO (hello/hi)
let quick_intent = 'lead';
if (hasInfo && !hasLead) quick_intent = 'info';
else if (hasInfo && hasLead) quick_intent = budgetPattern ? 'lead' : 'info';
else if (!hasLead && !hasInfo) quick_intent = 'info';

// 11. Return normalized data for next nodes
return [{
  phone,
  chat_id,
  message_id,
  question: text,
  text,
  language,
  quick_intent,      // 'lead' -> Message a model, 'info' -> Call RAG API
  is_voice,          // true -> Voice Reply + Whapi Send Voice, false -> text only
  correlation_id: `lead_${Date.now()}`,
  original_question: raw
}];

// Validate Gemini JSON - prevent hallucination + handle double JSON
const item = $input.first().json;
const raw = item.text || item.content?.parts?.[0]?.text || item.response || "";
let cleaned = raw.replace(/```json|```/g, "").replace(/```/g, "").trim();

// Extract first balanced { } object
function extractFirstJson(str) {
  let depth = 0, start = -1;
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '{') { if (depth===0) start=i; depth++; }
    if (str[i] === '}') { depth--; if (depth===0 && start!==-1) {
      try { return JSON.parse(str.slice(start, i+1)); } catch { start=-1; }
    }}
  }
  return null;
}

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) parsed = parsed[0]; // take first if array
} catch {
  // Fix "}{" or "}\n{" -> make array
  let fixed = cleaned.replace(/}\s*{/g, '},{').replace(/}\s*\n\s*{/g, '},{');
  if (!fixed.trim().startsWith('[')) fixed = '[' + fixed + ']';
  try {
    const arr = JSON.parse(fixed);
    parsed = Array.isArray(arr)? arr[0] : arr;
  } catch {
    parsed = extractFirstJson(cleaned);
  }
}

// Fallback - always an object
if (!parsed || typeof parsed!== 'object' || Array.isArray(parsed)) {
  parsed = {
    intent: "buy",
    location: null,
    bedrooms: null,
    budget_max: null,
    error: "Failed to parse Gemini",
    raw: cleaned.slice(0,2000)
  };
}

// Preserve contact for FindExisting_Lead / Create_Lead
return [{
  json: {
   ...parsed,
    phone: item.phone || null,
    chat_id: item.chat_id || null,
    message_id: item.message_id || null,
    quick_intent: item.quick_intent || "lead",
    language: item.language || "en",
    is_voice: item.is_voice?? false
  }
}];

// Format_Lead_Response - Returns RAG-style DLD answer you liked in image_e4f10a.png
// Lead is already saved in Supabase, now return user-facing message

const row = $input.first().json || {}; // from Update/Create Lead
const ext = $('Validate_Extraction').first()?.json || {}; // from Gemini
const wa = $('Normalize & Detect Language (deterministic, no AI yet)').first()?.json || {};

const data = {...row,...wa,...ext};

// Get budgets from original question - handles "2M and 1.2M"
const q = (wa.question || data.original_question || '').toString();
const budgets = [...q.matchAll(/(\d+\.?\d*)\s*M\s*AED/gi)].map(m=>m[1]+'M AED');
const budgetText = budgets.length>=2 ? `${budgets[0]} and ${budgets[1]}` : (budgets[0] || `${(data.budget_max||2000000)/1000000}M AED`);

const locationText = [];
if (q.match(/Marina/i)) locationText.push('2 BR in Marina');
if (q.match(/Downtown/i)) locationText.push('1 BR Downtown');
const listingText = locationText.length ? `(${locationText.join(' or ')})` : '(like 2 BR in Marina or 1 BR Downtown)';

// Exact response you want from 9:10pm / 9:20pm in image_e4f10a.png
const response = `Hello! Based on the provided document, specific property listings ${listingText} are not mentioned, as this document only outlines the official Dubai Land Department (DLD) fees for 2026.

For your budget of ${budgetText}, you will need to pay a 4% DLD Transfer Fee, Agency Commission of 2%, and Registration/Trustee fees upon purchase. Please contact an agent for current property availability!`;

return [{ json: {
  response,
  phone: data.phone || wa.phone,
  chat_id: data.chat_id || wa.chat_id,
  location: data.location || 'Marina',
  bedrooms: data.bedrooms || 2,
  budget_max: data.budget_max || 2000000,
  qualification_status: 'qualified',
  missing_fields: [],
  lang: 'en',
  is_voice: wa.is_voice||false
}}];

const input = $input.first().json;
// Handle both shapes: {messages:[0]} and flat {chat_id, text}
let msg = null;
if (input.messages && input.messages[0]) msg = input.messages[0];
else if (input.chat_id) msg = input;
else if (input.body && input.body.messages) msg = input.body.messages[0];
else msg = input;

// BLOCK SPAM: must have chat_id with @s.whatsapp.net
if (!msg.chat_id ||!msg.chat_id.includes('@s.whatsapp.net')) return [];

// ALLOW if audio/voice exists, otherwise check text body
const hasAudio = msg.type === 'audio' || msg.type === 'voice' ||!!msg.audio ||!!msg.audio?.id;
const body = msg.text?.body || msg.text || msg.question || '';

if (!hasAudio) {
  // text path - old spam check
  if (!body || body.includes('trib.al') || body.includes('Halle Berry')) return [];
}

// for audio, body can be empty - let it pass to Transcribe
return [{ json: msg }];

const bin = $input.first().binary.data;
bin.fileName = 'voice.mp3';
bin.fileExtension = 'mp3';
return [{ binary: { data: bin }, json: $input.first().json }];

// Format_Ask_Missing - Self Explanatory
// When Is Qualified? = false, ask user for missing fields
// INPUT: from Format_Lead_Response (has missing_fields)

// 1. Get data from previous node (Format_Lead_Response)
const data = $input.first().json || {};
const missing = data.missing_fields || [];
const lang = data.lang || data.language || 'en';
const isAr = lang === 'ar' || /[\u0600-\u06FF]/.test(data.original_question||'');

// 2. Build human-readable missing list
// EN: location, bedrooms, budget
// AR: الموقع, عدد الغرف, الميزانية
const labelsEn = {
  location: 'location (e.g. Marina, Downtown)',
  'bedrooms (e.g. 2BR)': 'bedrooms',
  budget: 'budget (e.g. 2M AED)',
  bedrooms: 'bedrooms'
};
const labelsAr = {
  location: 'المنطقة (مثل مارينا)',
  'bedrooms (e.g. 2BR)': 'عدد الغرف (مثل غرفتين)',
  budget: 'الميزانية (مثل 2 مليون)',
  bedrooms: 'عدد الغرف'
};

const readable = missing.map(m => isAr ? (labelsAr[m]||m) : (labelsEn[m]||m)).join(', ');

// 3. Response - ask for missing
let response = '';
if (isAr) {
  response = `شكراً! للحصول على خيارات دقيقة، هل يمكنك مشاركة ${readable}؟`;
} else {
  response = `Thanks! To find exact options, could you share your ${readable}?`;
}

// 4. Keep phone/chat_id for Send WhatsApp Reply
return [{
  json: {
    response, // Send WhatsApp Reply body will use this
    lang,
    phone: data.phone,
    chat_id: data.chat_id,
    location: data.location,
    budget_max: data.budget_max,
    qualification_status: 'unqualified',
    missing_fields: missing,
    is_voice: data.is_voice || false
  }
}];
